let state;
try { state = {...SEED,...JSON.parse(localStorage.getItem('postoryAdsDemo') || '{}')}; } catch { state = structuredClone(SEED); }
const names = {overview:'总览',clients:'客户管理',campaigns:'推广任务',approvals:'审批中心',delivery:'投放模拟',reports:'报告',connections:'平台授权',settings:'工作区设置'};
const money = n => '€' + Number(n).toLocaleString('en-IE',{minimumFractionDigits:0,maximumFractionDigits:0});
const moneyExact = n => '€' + Number(n).toLocaleString('en-IE',{minimumFractionDigits:2,maximumFractionDigits:2});
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const client = id => state.clients.find(c=>c.id===id) || state.clients[0];
const campaign = id => state.campaigns.find(c=>c.id===id);
function persist(){localStorage.setItem('postoryAdsDemo',JSON.stringify(state));}
function go(page){state.page=page;state.portal=false;render();}
function toast(message,kind=''){const el=document.createElement('div');el.className=`toast ${kind}`;el.textContent=message;document.querySelector('#toastRoot').append(el);setTimeout(()=>el.remove(),2600);}
function badge(label){let type='neutral';if(['已授权','通过','已通过','投放中','已完成','完成'].includes(label))type='success';else if(['待审批','待授权','续期提醒','学习中','审核中'].includes(label))type='warning';else if(['草稿','暂停','模拟运行'].includes(label))type='info';else if(['已退回','异常'].includes(label))type='danger';return `<span class="status status-${type}">${esc(label)}</span>`;}
function logo(c){return `<div class="client-logo ${c.tone||''}">${esc(c.initials)}</div>`;}
function getClientName(id){return esc(client(id).name);}
function heading(title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">POSTORY ADS STUDIO</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`;}
function stat(label,value,foot,icon='↗',trend=''){return `<article class="card stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-foot"><span class="${trend}">${foot}</span></div><i class="stat-accent"></i></article>`;}
function panelTitle(title,sub,action=''){return `<div class="panel-header"><div><div class="panel-title">${title}</div>${sub?`<div class="panel-subtitle">${sub}</div>`:''}</div>${action}</div>`;}
function chart(){return `<div class="chart-wrap"><div class="chart-grid"><span><small>$8k</small></span><span><small>$6k</small></span><span><small>$4k</small></span><span><small>$2k</small></span><span><small>$0</small></span></div><svg class="chart-svg" viewBox="0 0 700 160" preserveAspectRatio="none" aria-label="七日广告消耗趋势图"><defs><linearGradient id="spendFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#df0075" stop-opacity=".16"/><stop offset="1" stop-color="#df0075" stop-opacity="0"/></linearGradient></defs><path d="M0 127 C38 113 48 118 80 105 S123 95 150 102 S193 68 230 76 S277 92 309 66 S357 75 384 59 S431 68 462 47 S511 66 540 40 S587 49 615 27 S670 35 700 12 L700 160 L0 160 Z" fill="url(#spendFill)"/><path d="M0 127 C38 113 48 118 80 105 S123 95 150 102 S193 68 230 76 S277 92 309 66 S357 75 384 59 S431 68 462 47 S511 66 540 40 S587 49 615 27 S670 35 700 12" fill="none" stroke="#df0075" stroke-width="2.5" vector-effect="non-scaling-stroke"/><path d="M0 145 C42 138 54 125 80 130 S123 122 150 127 S194 118 230 116 S277 121 309 109 S357 115 384 100 S431 108 462 95 S511 100 540 86 S587 97 615 78 S669 90 700 67" fill="none" stroke="#ff9a49" stroke-width="2" stroke-dasharray="4 4" vector-effect="non-scaling-stroke"/></svg><div class="chart-labels"><span>10/20</span><span>10/21</span><span>10/22</span><span>10/23</span><span>10/24</span><span>10/25</span><span>10/26</span></div></div>`;}
function clientRows(){return state.clients.slice(0,4).map(c=>`<div class="client-row" data-action="client" data-id="${c.id}">${logo(c)}<div class="client-meta"><b>${esc(c.name)}</b><small>${esc(c.platform)} · ${esc(c.sector)}</small></div><div class="client-kpi"><b>${c.spend?money(c.spend):'—'}</b>7 日消耗</div></div>`).join('');}
function campaignTable(items=state.campaigns.slice(0,5), portalMode=false){if(!items.length)return `<div class="empty-state">◫<strong>这里还没有推广任务</strong>计划创建后会显示在这里。</div>`;return `<div class="table-wrap"><table class="table"><thead><tr><th>计划名称</th><th>客户</th><th>平台</th><th>预算 / 日</th><th>状态</th><th>ROAS</th>${portalMode?'':'<th></th>'}</tr></thead><tbody>${items.map(c=>`<tr><td><div class="row-name">${esc(c.name)}</div><div class="row-sub">${esc(c.id)} · ${esc(c.objective)}</div></td><td>${getClientName(c.clientId)}</td><td>${esc(c.platform)}</td><td>${money(c.budget)}</td><td>${badge(c.status)}</td><td>${esc(c.roas)}</td>${portalMode?'':`<td><button class="inline-link" data-action="campaign-detail" data-id="${c.id}">查看</button></td>`}</tr>`).join('')}</tbody></table></div>`;}
function restaurantJourney(){return `<section class="card panel journey-panel">${panelTitle('一项优惠，从客户确认到经营复盘','示例客户：Harbour Table · Dublin 2 · 周一至周四双人晚餐优惠',`<button class="button button-primary button-small" data-action="new-campaign" data-client="field">＋ 新建推广任务</button>`)}<div class="journey-track"><div class="journey-node"><i>1</i><b>客户配置</b><small>客户确认预约目标、€20/天、€140/周、门店周边 5 km 与 Meta 授权</small><em class="owner-client">客户确认</em></div><div class="journey-node"><i>2</i><b>推广任务</b><small>运营选优惠、日期、预约入口；继承客户长期设置</small><em class="owner-ops">运营建立</em></div><div class="journey-node"><i>3</i><b>复用素材与预检</b><small>系统从 PoStory 素材生成广告版本，检查链接、预算和权限</small><em class="owner-auto">系统自动</em></div><div class="journey-node"><i>4</i><b>异常审批</b><small>授权范围内自动提交；超预算、新优惠或追踪异常才停下请人确认</small><em class="owner-exception">仅异常审批</em></div><div class="journey-node"><i>5</i><b>巡检与报告</b><small>系统巡检花费与投放状态；周报呈现预约、核销和销售数据</small><em class="owner-auto">系统自动</em></div></div><div class="journey-rule"><span>自动化边界</span> 客户授权内：按预算运行、日常巡检、生成周报。<b>必须人工确认：</b>新渠道/新优惠、预算上限变更、授权失效、素材或落地页问题。</div></section>`;}
function overview(){let pending=state.approvals.filter(a=>a.status!=='已通过'&&a.status!=='已退回').length;return `${heading('本周运营概览','以 Harbour Table 都柏林餐厅为例：一项优惠任务从客户确认，到系统巡检和到店复盘。以下均为模拟数据。',`<button class="button button-secondary" data-action="report-download">↓ 导出概览</button><button class="button button-primary" data-action="new-campaign">＋ 新建推广任务</button>`)}${restaurantJourney()}<div class="grid stats-grid">${stat('管理中的客户','06','4 个平台账户已连接','♧')}${stat('本周广告消耗','€1,840','较上周 +12.8%','↗','trend-up')}${stat('综合 ROAS','—','演示任务不汇总跨平台收入','⌁','trend-up')}${stat('待处理审批',String(pending).padStart(2,'0'),pending?'需要你或客户确认':'当前无待处理','✓','trend-down')}</div><div class="grid overview-grid"><section class="card panel">${panelTitle('账户表现','近 7 天 · 演示账户 · EUR',`<button class="link-button" data-page="reports">查看报告 →</button>`)}${chart()}<div class="legend-row"><div class="chart-legend"><span><i></i>广告消耗</span><span><i class="orange"></i>转化价值</span></div><span class="result-count">同步于 10/27 09:15</span></div></section><section class="card panel">${panelTitle('客户账户','6 个活跃客户',`<button class="link-button" data-page="clients">全部客户 →</button>`)}<div class="client-list">${clientRows()}</div></section></div><div class="grid lower-grid"><section class="card panel">${panelTitle('近期推广任务','跨客户计划状态一览',`<button class="link-button" data-page="campaigns">全部计划 →</button>`)}${campaignTable()}</section><section class="card panel">${panelTitle('最近动态','工作区最新操作') }<div class="activity-list"><div class="activity"><div class="activity-dot">✓</div><div><b>Harbour Table · 本周优惠任务已巡检</b><p>7 天 · €20/日上限 · 预约数据待回传</p><time>今天 09:14</time></div></div><div class="activity"><div class="activity-dot">↗</div><div><b>Northstar · 计划进入学习期</b><p>轻户外新品种草 · TikTok Ads</p><time>今天 08:36</time></div></div><div class="activity"><div class="activity-dot">⌑</div><div><b>Little Fern · 计划等待审批</b><p>审批队列只处理越界或异常事项</p><time>今天 08:12</time></div></div></div></section></div>`;}
function clientsPage(){return `${heading('客户管理','管理每位客户独立的平台授权、账户和广告目标。',`<button class="button button-primary" data-action="new-client">＋ 添加客户</button>`)}<div class="filter-row"><label class="search-field">⌕ <input id="clientSearch" placeholder="搜索客户名称或联系人"></label><select class="pill-filter" id="clientFilter"><option value="all">全部授权状态</option><option>已授权</option><option>待授权</option><option>续期提醒</option></select><button class="pill-filter" data-action="toast" data-message="客户列表已更新">最近更新 ⌄</button></div><div id="clientGrid" class="grid client-grid">${state.clients.map(c=>clientCard(c)).join('')}</div>`;}
function clientCard(c){return `<article class="card client-card" data-client-card="${c.id}"><div class="client-card-top">${logo(c)}<div class="client-card-title"><b>${esc(c.name)}</b><small>${esc(c.sector)} · ${esc(c.contact)}</small></div><button class="more" data-action="client" data-id="${c.id}">···</button></div><p>${esc(c.description)}</p><div class="client-card-stats"><div><b>${money(c.spend)}</b>7 日消耗</div><div><b>${esc(c.roas)}</b>综合 ROAS</div><div><b>${c.campaigns}</b>计划</div></div><div class="client-card-bottom">${badge(c.auth)}<button class="inline-link" data-action="client" data-id="${c.id}">查看客户 →</button></div></article>`;}
function clientDetail(){const c=client(state.clientId);let authorized=c.auth==='已授权';return `${heading('客户空间','每位客户拥有独立授权、广告账户、审批和报告。',`<button class="button button-secondary" data-page="clients">← 返回客户</button><button class="button button-secondary" data-action="client-setup" data-client="${c.id}">配置目标 / 预算 / 服务区域</button><button class="button button-primary" data-action="new-campaign" data-client="${c.id}">＋ 为该客户建推广任务</button>`)}<div class="card client-profile-card">${logo(c)}<div class="client-profile-info"><h2>${esc(c.name)} ${badge(c.auth)}</h2><p>${esc(c.sector)} · 客户负责人 ${esc(c.contact)} · ${esc(c.email)}</p></div><button class="button button-secondary button-small" data-action="client-report" data-client="${c.id}">查看客户入口 ↗</button></div><div class="section-tabs"><button class="${state.clientTab==='overview'?'active':''}" data-action="client-tab" data-tab="overview">账户概况</button><button class="${state.clientTab==='auth'?'active':''}" data-action="client-tab" data-tab="auth">平台授权</button><button class="${state.clientTab==='campaigns'?'active':''}" data-action="client-tab" data-tab="campaigns">推广任务</button></div>${state.clientTab==='overview'?`<div class="grid detail-grid"><section class="card panel">${panelTitle('授权与连接','客户专属的广告平台访问权限',`<button class="link-button" data-action="client-tab" data-tab="auth">管理授权 →</button>`)}<div class="platform-row"><div class="platform-logo">f</div><div class="platform-copy"><b>${esc(c.platform)}</b><small>${authorized?`广告账户 ${esc(c.account)}`:'尚未连接客户账户'}</small></div>${badge(c.auth)}${authorized?'<button class="button button-secondary button-small" data-action="toast" data-message="授权详情仅为演示数据">详情</button>':`<button class="button button-primary button-small" data-action="authorize" data-id="${c.id}">发起授权</button>`}</div><div class="notice" style="margin-top:13px"><i>ⓘ</i><span>客户的授权令牌应按客户空间加密存储，任何运营人员都不能跨客户复用。</span></div></section><section class="card panel">${panelTitle('客户业务信息','用于计划与报告的默认上下文')}<div class="split-cards"><div class="info-box"><small>主要联系人</small><b>${esc(c.contact)}</b></div><div class="info-box"><small>默认币种</small><b>EUR · 欧元</b></div><div class="info-box"><small>账户时区</small><b>Europe/Dublin</b></div><div class="info-box"><small>客户行业</small><b>${esc(c.sector)}</b></div></div></section><section class="card panel">${panelTitle('客户工作流','当前业务进展')}<div class="flow-step"><div class="step-number done">✓</div><div><b>客户资料已建立</b><p>负责人和报告设置已录入。</p></div></div><div class="flow-step"><div class="step-number ${authorized?'done':''}">${authorized?'✓':'2'}</div><div><b>客户独立授权 ${authorized?'已完成':'待完成'}</b><p>客户确认平台和账户访问范围。</p></div></div><div class="flow-step"><div class="step-number ${c.campaigns?'done':''}">${c.campaigns?'✓':'3'}</div><div><b>推广任务与异常审批</b><p>授权内常规任务自动运行；只有越界或异常才需审批。</p></div></div></section><section class="card panel">${panelTitle('最近 7 天',`平台归因数据 · ${esc(c.platform)}`)}<div class="split-cards"><div class="info-box"><small>广告消耗</small><b>${money(c.spend)}</b></div><div class="info-box"><small>ROAS</small><b>${esc(c.roas)}</b></div><div class="info-box"><small>活跃计划</small><b>${c.campaigns} 个</b></div><div class="info-box"><small>同步状态</small><b style="color:var(--success)">● 已更新</b></div></div></section></div>`:state.clientTab==='auth'?authorizationTab(c):`<section class="card panel">${panelTitle('客户推广任务','该客户空间内的计划与审批')}${campaignTable(state.campaigns.filter(x=>x.clientId===c.id))}</section>`}`;}
function authorizationTab(c){let authorized=c.auth==='已授权';return `<div class="grid detail-grid"><section class="card panel">${panelTitle('平台授权','客户确认后才能访问其广告账户',`<span class="result-count">授权范围仅绑定此客户</span>`)}<div class="platform-row"><div class="platform-logo">${c.platform.includes('Google')?'G':c.platform.includes('TikTok')?'♪':'f'}</div><div class="platform-copy"><b>${esc(c.platform)}</b><small>${authorized?`账户：${esc(c.account)}`:'由客户本人完成登录和授权'}</small></div>${badge(c.auth)}</div><div style="padding:14px 2px 2px"><div class="eyebrow">请求的权限范围</div><div class="flow-step"><div class="step-number done">✓</div><div><b>读取广告账户与基础信息</b><p>确认客户选择的账户和名称。</p></div></div><div class="flow-step"><div class="step-number done">✓</div><div><b>读取投放数据与报告</b><p>获取消耗、点击、转化和归因窗口信息。</p></div></div><div class="flow-step"><div class="step-number">3</div><div><b>管理客户确认的推广任务</b><p>任何预算变更与新计划都必须通过独立审批。</p></div></div></div><div class="notice warning"><i>!</i><span>这是演示页面，不会打开平台登录，也不会获得任何真实权限。实际授权应使用平台 OAuth 并校验客户身份。</span></div><div style="margin-top:13px">${authorized?`<button class="button button-secondary button-small" data-action="revoke-auth" data-id="${c.id}">模拟撤销授权</button>`:`<button class="button button-primary" data-action="authorize" data-id="${c.id}">邀请客户完成授权 →</button>`}</div></section><section class="card panel">${panelTitle('授权事件','客户授权审计轨迹')}<div class="activity-list"><div class="activity"><div class="activity-dot">${authorized?'✓':'⌑'}</div><div><b>${authorized?'客户已确认账户访问':'等待客户确认'}</b><p>${authorized?`${esc(c.contact)} · ${esc(c.platform)}`:'邀请链接只对本客户有效；客户可随时拒绝或撤销。'}</p><time>${authorized?'10/24 14:32':'尚未发生'}</time></div></div><div class="activity"><div class="activity-dot">i</div><div><b>运营创建客户工作区</b><p>PoStory Agency · 客户边界已建立</p><time>10/12 11:08</time></div></div></div></section></div>`;}
function campaignsPage(){let items=state.campaigns;return `${heading('推广任务','每张任务卡代表一次生意目标；平台 Campaign 与广告组由系统映射管理。',`<button class="button button-primary" data-action="new-campaign">＋ 新建推广任务</button>`)}<div class="grid stats-grid">${stat('全部计划',String(items.length).padStart(2,'0'),'当前演示工作区','▤')}${stat('投放中',String(items.filter(c=>['投放中','学习中'].includes(c.status)).length).padStart(2,'0'),'包含学习期计划','◉')}${stat('待审批',String(state.approvals.filter(a=>!['已通过','已退回'].includes(a.status)).length).padStart(2,'0'),'需运营或客户确认','✓')}${stat('本周模拟消耗',money(items.reduce((n,c)=>n+c.spent,0)),'演示币种 · EUR','↗')}</div><div class="card panel">${panelTitle('所有推广任务','客户空间隔离 · 变更审批通过后才能模拟投放') }<div class="filter-row"><label class="search-field">⌕ <input id="campaignSearch" placeholder="搜索计划或客户"></label><select class="pill-filter" id="campaignFilter"><option value="all">所有状态</option><option>投放中</option><option>待审批</option><option>草稿</option><option>已完成</option></select><select class="pill-filter" id="campaignClient"><option value="all">所有客户</option>${state.clients.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div id="campaignTable">${campaignTable(items)}</div></div>`;}
function approvalsPage(){let pending=state.approvals.filter(a=>!['已通过','已退回'].includes(a.status));return `${heading('审批中心','先核对每个客户的预算、账户和投放参数，再批准模拟投放。',`<span class="result-count">审批绑定客户与计划版本</span>`)}<div class="approval-layout"><section class="card panel">${panelTitle('待你处理',`${pending.length} 项待确认`)}${pending.length?pending.map(a=>approvalCard(a)).join(''):`<div class="empty-state">✓<strong>审批队列已清空</strong>待处理的计划会出现在这里。</div>`}${panelTitle('已处理',`${state.approvals.filter(a=>['已通过','已退回'].includes(a.status)).length} 项`)}${state.approvals.filter(a=>['已通过','已退回'].includes(a.status)).map(a=>approvalCard(a,true)).join('')}</section><aside class="card panel">${panelTitle('审批前检查','每项计划必须逐项核对')}<div class="flow-step"><div class="step-number done">1</div><div><b>核实客户与账户</b><p>确认账户归属正确，客户授权仍有效。</p></div></div><div class="flow-step"><div class="step-number done">2</div><div><b>核对总预算与每日上限</b><p>确认币种、持续时间和最高花费。</p></div></div><div class="flow-step"><div class="step-number done">3</div><div><b>查看素材和目标</b><p>审核平台、投放目标及广告文案。</p></div></div><div class="flow-step"><div class="step-number">4</div><div><b>记录审批人和计划版本</b><p>任何审批后修改都需要重新审批。</p></div></div><div class="notice warning" style="margin-top:12px"><i>!</i><span>正常授权范围内的任务可自动执行；此演示审批队列展示的是需要人工确认的例外事项，不会提交真实广告变更。</span></div></aside></div>`;}
function approvalCard(a,done=false){let c=campaign(a.campaignId);if(!c)return '';let cl=client(a.clientId);return `<article class="card approval-card"><div class="approval-card-head">${logo(cl)}<div class="approval-title"><b>${esc(a.name)}</b><small>${esc(cl.name)} · ${esc(a.id)} · ${esc(a.submitted)}</small></div>${badge(a.status||'待审批')}</div><div class="approval-metrics"><div><small>每日预算</small><b>${money(c.budget)} EUR</b></div><div><small>投放周期</small><b>${esc(c.date)}</b></div><div><small>广告平台</small><b>${esc(c.platform)} Ads</b></div></div><div class="notice"><i>◉</i><span>${esc(a.note)}<br>目标：${esc(c.objective)} · 预估周期上限 ${money(c.budget*10)}</span></div><div class="approval-actions"><span class="result-count">账户 ${esc(cl.account)} · 版本 v1</span><div class="actions">${done?`<button class="button button-secondary button-small" data-action="campaign-detail" data-id="${c.id}">查看计划</button>`:`<button class="button button-secondary button-small" data-action="reject" data-id="${a.id}">退回修改</button><button class="button button-primary button-small" data-action="approve" data-id="${a.id}">✓ 通过审批</button>`}</div></div></article>`;}
function deliveryPage(){let live=state.campaigns.filter(c=>['投放中','学习中','模拟运行','暂停','已完成'].includes(c.status));return `${heading('投放模拟','用演示状态走通平台回执、学习期、投放、暂停和报告流程。',`<span class="status status-warning">● 无平台连接 · 仅模拟</span>`)}<div class="notice warning" style="margin-bottom:15px"><i>!</i><span>此页不会触发真实投放或广告费用。状态流转仅更新本机浏览器的演示数据。</span></div><div class="grid delivery-grid">${live.slice(0,3).map(c=>deliveryCard(c)).join('')}</div><section class="card panel">${panelTitle('已批准 / 可模拟启动','所有待审批或授权未完成的计划都不能开始。')}${campaignTable(state.campaigns.filter(c=>['草稿','已批准','待审批'].includes(c.status)))}</section>`;}
function deliveryCard(c){let cl=client(c.clientId),step=c.status==='学习中'?1:c.status==='投放中'||c.status==='模拟运行'?2:c.status==='暂停'?2:3;return `<article class="card delivery-card"><div class="delivery-top"><b>${esc(c.name)}</b>${badge(c.status)}</div><p style="margin-top:4px">${esc(cl.name)} · ${esc(c.platform)} Ads</p><div class="state-steps">${[0,1,2,3].map((n)=>`<span class="state-dot ${n<step?'complete':n===step?'current':''}">${n<step?'✓':n+1}</span>${n<3?`<i class="state-line ${n<step?'complete':''}"></i>`:''}`).join('')}</div><div class="delivery-bottom"><span>审核通过</span><span>学习中</span><span>投放中</span><span>已完成</span></div><h3>${moneyExact(c.spent)} <small style="font-size:10px;color:#909bb0;font-weight:500">模拟消耗</small></h3><div class="progress-track"><span style="width:${Math.min(100,c.progress)}%"></span></div><div class="delivery-bottom"><span>每日上限 ${money(c.budget)}</span><span>${c.progress}% 周期进度</span></div><div class="heading-actions" style="justify-content:flex-end;margin-top:14px">${c.status==='投放中'||c.status==='学习中'||c.status==='模拟运行'?`<button class="button button-secondary button-small" data-action="pause" data-id="${c.id}">Ⅱ 暂停模拟</button><button class="button button-soft button-small" data-action="simulate" data-id="${c.id}">推进一天 →</button>`:c.status==='暂停'?`<button class="button button-primary button-small" data-action="resume" data-id="${c.id}">▶ 恢复模拟</button>`:`<button class="button button-primary button-small" data-action="simulate" data-id="${c.id}">▶ 启动模拟</button>`}</div></article>`;}
function reportsPage(){let total=state.clients.reduce((n,c)=>n+c.spend,0);return `${heading('报告与表现','在清楚标注币种、时区和归因口径的前提下复核客户表现。',`<button class="button button-secondary" data-action="report-download">↓ 导出 CSV</button><button class="button button-primary" data-action="client-portal">预览客户报告 ↗</button>`)}<section class="card panel restaurant-report">${panelTitle('Harbour Table · 店主关心的结果','工作日晚餐优惠 · 演示周期 7 天 · 爱尔兰 / EUR',`<span class="status status-info">演示数据 · 尚未连接预约/POS</span>`)}<div class="merchant-results"><div><small>广告花费</small><b>€118.40</b><em>预算上限 €140</em></div><div><small>优惠券领取</small><b>34</b><em>平台表单记录</em></div><div><small>确认预约</small><b>9</b><em>预约系统同步 · 演示</em></div><div><small>实际到店核销</small><b>待回传</b><em>需要店员扫码或 POS 数据</em></div></div><div class="notice"><i>i</i><span>领取和预约代表顾客有兴趣，不等于实际到店或消费。只有预约系统、优惠码核销或 POS 回传后，才计为已验证到店/销售；CTR、点击量放在平台数据详情。</span></div></section><div class="filter-row"><select id="reportClient" class="pill-filter"><option value="all">所有客户</option>${state.clients.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><button class="date-button" data-action="toast" data-message="报告日期范围：最近 7 天">最近 7 天　⌄</button><span class="result-count">数据更新于 10/27 09:15 · Europe/Dublin · EUR</span></div><div class="grid report-kpis">${stat('广告消耗',money(total),'模拟账面累计','↗')}${stat('平台归因收入','€5,920','平台归因 · 7 日','▤','trend-up')}${stat('综合 ROAS','3.24×','不可跨平台直接比较','⌁')}${stat('总点击','18,490','平台汇总 · 7 日','◎')}</div><div class="grid report-grid"><section class="card panel">${panelTitle('客户表现','近 7 天 · 按客户空间汇总')}${chart()}<div class="legend-row"><div class="chart-legend"><span><i></i>广告消耗</span><span><i class="orange"></i>转化价值</span></div><span class="result-count">模拟趋势</span></div></section><section class="card panel">${panelTitle('报告口径说明','实际接入后按平台逐项披露')}<div class="flow-step"><div class="step-number done">i</div><div><b>平台币种</b><p>各账户独立展示；当前演示账户以 EUR，不代表发生汇率转换。</p></div></div><div class="flow-step"><div class="step-number done">i</div><div><b>平台归因</b><p>收入按平台归因口径统计，可能与其他平台重叠。</p></div></div><div class="flow-step"><div class="step-number done">i</div><div><b>更新时间与时区</b><p>显示数据同步时间以及客户账户时区。</p></div></div></section></div><section class="card panel" style="margin-top:15px">${panelTitle('客户报告','点击客户可查看该客户独立入口')}<div class="table-wrap"><table class="table"><thead><tr><th>客户</th><th>广告消耗</th><th>平台归因收入</th><th>ROAS</th><th>活跃计划</th><th>授权状态</th><th></th></tr></thead><tbody>${state.clients.map(c=>`<tr><td><span class="mini-avatar">${esc(c.initials)}</span><b class="row-name">${esc(c.name)}</b></td><td>${money(c.spend)}</td><td>${c.spend?money(c.spend*3.24):'—'}</td><td>${esc(c.roas)}</td><td>${c.campaigns}</td><td>${badge(c.auth)}</td><td><button class="inline-link" data-action="client-report" data-client="${c.id}">客户入口 ↗</button></td></tr>`).join('')}</tbody></table></div></section>`;}
function clientPortal(){let c=client(state.clientId);let tabs=state.portalTab;return `<div class="client-portal"><div class="portal-banner"><b>客户入口预览</b><span>当前以 ${esc(c.name)} 的客户身份查看 · 页面数据为模拟信息</span><button data-action="exit-portal">← 返回运营台</button></div><div class="portal-header"><div class="portal-brand">${logo(c)}<div><b>${esc(c.name)}</b><small>客户广告工作区 · 由 PoStory 提供</small></div></div><div class="portal-user"><div class="avatar avatar-pink">${esc(c.contact.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div>${esc(c.contact)}　⌄</div></div><div class="portal-tabs"><button class="${tabs==='overview'?'active':''}" data-action="portal-tab" data-tab="overview">账户概况</button><button class="${tabs==='campaigns'?'active':''}" data-action="portal-tab" data-tab="campaigns">推广任务</button><button class="${tabs==='reports'?'active':''}" data-action="portal-tab" data-tab="reports">月度报告</button><button class="${tabs==='approvals'?'active':''}" data-action="portal-tab" data-tab="approvals">待我审批</button><button class="${tabs==='access'?'active':''}" data-action="portal-tab" data-tab="access">平台授权</button></div>${tabs==='overview'?`<div class="portal-report">${c.id==='field'?`<section class="card panel restaurant-report">${panelTitle('您的工作日晚餐优惠','系统会按已授权预算运行；异常时再请您确认',`<span class="status status-success">授权上限 €20/天 · €140/周</span>`)}<div class="merchant-results"><div><small>广告花费</small><b>€118.40</b><em>本周模拟</em></div><div><small>优惠券领取</small><b>34</b><em>平台表单 · 模拟</em></div><div><small>确认预约</small><b>9</b><em>预约数据 · 模拟</em></div><div><small>到店核销</small><b>待回传</b><em>连接收银/POS 后更新</em></div></div></section>`:''}<div class="page-heading"><div><h1 style="font-size:21px">您好，${esc(c.contact.split(' ')[0])}</h1><p>这是您的账户表现和需要您确认的事项。</p></div><div class="heading-actions"><button class="button button-secondary button-small" data-action="client-setup" data-client="${c.id}">首次配置目标 / 预算 / 服务区域</button><button class="button button-secondary button-small" data-action="report-download">↓ 下载报告</button></div></div><div class="grid stats-grid">${stat('近 7 天广告消耗',money(c.spend),'客户账户币种 EUR','↗')}${stat('平台归因收入',c.spend?money(c.spend*3.24):'—','平台归因口径','▤','trend-up')}${stat('广告回报 ROAS',esc(c.roas),'近 7 天','⌁')}${stat('待您确认',String(state.approvals.filter(a=>a.clientId===c.id&&!['已通过','已退回'].includes(a.status)).length).padStart(2,'0'),'可在待我审批查看','✓','trend-down')}</div><div class="card panel">${panelTitle('账户表现','近 7 天 · EUR')} ${chart()}<div class="notice" style="margin-top:10px"><i>i</i><span>实际数据将注明广告平台归因窗口、币种、时区与最后同步时间。图表为原型模拟数据。</span></div></div><section class="card panel" style="margin-top:14px">${panelTitle('近期推广任务','仅限您的客户空间')}${campaignTable(state.campaigns.filter(x=>x.clientId===c.id),true)}</section></div>`:tabs==='campaigns'?`<section class="card panel">${panelTitle('您的推广任务','当前账户内的计划状态')}${campaignTable(state.campaigns.filter(x=>x.clientId===c.id),true)}</section>`:tabs==='reports'?`<section class="card panel">${panelTitle('月度表现报告','2026 年 10 月 · 模拟数据',`<button class="button button-secondary button-small" data-action="report-download">↓ 下载 CSV</button>`)}<div class="grid report-kpis">${stat('广告消耗',money(c.spend),'EUR','↗')}${stat('平台归因收入',c.spend?money(c.spend*3.24):'—','平台归因','▤')}${stat('ROAS',esc(c.roas),'模拟数据','⌁')}${stat('已投放天数','18','截至 10/27','◎')}</div>${chart()}<div class="notice"><i>i</i><span>平台数据可能采用不同归因窗口，收入可能与其他渠道报告重叠。此报告仅用于原型演示。</span></div></section>`:tabs==='approvals'?`<section class="card panel">${panelTitle('需要您确认','仅显示属于您的客户空间的审批')} ${state.approvals.filter(a=>a.clientId===c.id&&!['已通过','已退回'].includes(a.status)).map(a=>approvalCard(a)).join('')||'<div class="empty-state">✓<strong>目前没有待您确认的计划</strong>新的推广任务送审后会出现在这里。</div>'}</section>`:`<section class="card panel">${panelTitle('平台授权','您可以随时查看或撤销账户访问')}<div class="platform-row"><div class="platform-logo">f</div><div class="platform-copy"><b>${esc(c.platform)}</b><small>${c.auth==='已授权'?`账户 ${esc(c.account)}`:'等待您完成授权'}</small></div>${badge(c.auth)}${c.auth==='已授权'?`<button class="button button-secondary button-small" data-action="revoke-auth" data-id="${c.id}">撤销授权</button>`:`<button class="button button-primary button-small" data-action="authorize" data-id="${c.id}">开始授权</button>`}</div><div class="notice warning" style="margin-top:14px"><i>!</i><span>此为界面演示。真实账户连接需在正式产品中使用安全 OAuth 登录，并由您确认授权。</span></div></section>`}</div>`;}
function connectionsPage(){return `${heading('平台授权','查看各客户独立的授权连接和平台状态。',`<button class="button button-secondary" data-page="clients">查看客户 →</button>`)}<div class="notice warning" style="margin-bottom:15px"><i>!</i><span>此原型没有 Meta、TikTok 或 Google 的真实应用密钥。下方连接状态仅作流程示意。</span></div><div class="grid client-grid">${state.clients.map(c=>`<section class="card panel">${panelTitle(`${esc(c.name)}`,badge(c.auth))}<div class="platform-row"><div class="platform-logo">${c.platform.includes('Google')?'G':c.platform.includes('TikTok')?'♪':'f'}</div><div class="platform-copy"><b>${esc(c.platform)}</b><small>${c.auth==='已授权'?esc(c.account):'等待客户完成独立授权'}</small></div></div><div class="client-card-bottom"><span class="result-count">最后核验：${c.auth==='已授权'?'10/24 14:32':'—'}</span>${c.auth==='已授权'?`<button class="inline-link" data-action="revoke-auth" data-id="${c.id}">撤销</button>`:`<button class="inline-link" data-action="authorize" data-id="${c.id}">发起邀请 →</button>`}</div></section>`).join('')}</div>`;}
function settingsPage(){return `${heading('工作区设置','管理运营工作区的默认值与安全流程。',`<button class="button button-secondary" data-action="toast" data-message="设置已保存（仅本地模拟）">保存更改</button>`)}<div class="grid detail-grid"><section class="card panel">${panelTitle('工作区信息','内部运营')}<div class="form-grid"><div class="form-field"><label>工作区名称</label><input value="PoStory Agency"></div><div class="form-field"><label>默认币种</label><select><option>EUR · 欧元</option><option>CAD · 加元</option></select></div><div class="form-field"><label>报告时区</label><select><option>Europe/Dublin</option></select></div><div class="form-field"><label>审批策略</label><select><option>授权范围内自动运行；超出边界才审批</option></select></div></div></section><section class="card panel">${panelTitle('投放安全规则','平台提交前检查')}<div class="flow-step"><div class="step-number done">✓</div><div><b>客户授权失效时阻止提交</b><p>未授权或已撤销的客户不能创建广告。</p></div></div><div class="flow-step"><div class="step-number done">✓</div><div><b>审批绑定计划版本与预算</b><p>审批后任何改动都重新进入审批。</p></div></div><div class="flow-step"><div class="step-number done">✓</div><div><b>新广告从暂停状态创建</b><p>先核对平台回执，再由授权人员启动。</p></div></div></section></div>`;}
function render(){document.querySelectorAll('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',!state.portal&&b.dataset.page===state.page));document.querySelector('#breadcrumb').textContent=state.portal?'客户入口':(state.page==='client-detail'?client(state.clientId).name:names[state.page]||'总览');document.querySelector('#approvalCount').textContent=state.approvals.filter(a=>!['已通过','已退回'].includes(a.status)).length;let html;if(state.portal)html=clientPortal();else if(state.page==='client-detail')html=clientDetail();else html=({overview,clients:clientsPage,campaigns:campaignsPage,approvals:approvalsPage,delivery:deliveryPage,reports:reportsPage,connections:connectionsPage,settings:settingsPage}[state.page]||overview)();document.querySelector('#pageContent').innerHTML=html;persist();}
function clientSetupModal(clientId){let c=client(clientId||state.clientId);state.setup={clientId:c.id,step:1,objective:c.settings?.objective||'门店到访',budget:c.settings?.budget||600,daily:c.settings?.daily||20,region:c.settings?.region||'Dublin 2 · 门店周边 5 km',audience:c.settings?.audience||'附近居民与上班族；英语为主；平台自动优化',platforms:c.settings?.platforms||[c.platform.replace(' Ads','')]};renderClientSetup();}
function newClientModal(){document.querySelector('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><div><h2>添加客户</h2><p>先建立客户空间，再让客户确认目标、预算上限和服务区域。受众由系统推荐、运营把关。</p></div><button class="modal-close" data-action="close-modal">×</button></div><div class="form-grid"><div class="form-field full"><label>客户 / 品牌名称</label><input id="newClientName" placeholder="例如：Harbour Goods"></div><div class="form-field"><label>客户联系人</label><input id="newClientContact" placeholder="例如：Alex Chen"></div><div class="form-field"><label>联系邮箱</label><input id="newClientEmail" type="email" placeholder="例如：alex@example.com"></div><div class="form-field full"><label>行业</label><select id="newClientSector"><option>电商零售</option><option>家居生活</option><option>服饰电商</option><option>餐饮零售</option><option>专业服务</option><option>其他</option></select></div></div><div class="notice warning" style="margin-top:13px"><i>!</i><span>这是浏览器本地演示。不会发送邀请邮件或创建真实客户账户。</span></div><div class="modal-actions"><button class="button button-secondary" data-action="close-modal">取消</button><button class="button button-primary" data-action="create-demo-client">建立客户空间 →</button></div></div></div>`;}
function renderClientSetup(){let d=state.setup;if(!d)return;let c=client(d.clientId);let platforms=['Meta','TikTok','Google','Apple Search Ads','Microsoft Ads','Reddit Ads'];let recommended=d.objective.includes('视频')?['TikTok']:d.objective.includes('网站访问')?['Google']:[c.platform.replace(' Ads','')];let step2=d.step===2;document.querySelector('#modalRoot').innerHTML=`<div class="modal-backdrop" data-action="modal-bg"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="setupTitle"><div class="modal-head"><div><div class="eyebrow">客户首次配置 · ${esc(c.name)}</div><h2 id="setupTitle">${step2?'确认平台建议':'先告诉我们你希望广告做到什么'}</h2><p>用日常语言设定客户基线，后续计划会自动沿用，可随时修改。</p></div><button class="modal-close" data-action="close-modal">×</button></div><div class="wizard-steps"><div class="wizard-step ${step2?'done':'active'}"><span>${step2?'✓':'1'}</span>目标、预算和区域</div><i class="wizard-line"></i><div class="wizard-step ${step2?'active':''}"><span>2</span>推荐渠道与账户</div></div>${!step2?`<div class="form-grid"><div class="form-field full"><label>这次最希望带来什么结果？</label><select id="setupObjective"><option ${d.objective==='销售 / 订单'?'selected':''}>销售 / 订单</option><option ${d.objective==='网站访问'?'selected':''}>网站访问</option><option ${d.objective==='潜在客户'?'selected':''}>潜在客户</option><option ${d.objective==='品牌认知 / 视频观看'?'selected':''}>品牌认知 / 视频观看</option><option ${d.objective==='预约到店'?'selected':''}>预约到店</option><option ${d.objective==='门店到访'?'selected':''}>门店到访</option><option ${d.objective==='应用安装'?'selected':''}>应用安装</option></select><span class="field-hint">系统会优先优化这个结果。客户确认后作为默认目标，不用每周重填。</span></div><div class="form-field"><label>每月最多花费（${esc(c.settings?.currency||'EUR')}）</label><input id="setupBudget" type="number" min="0" step="100" value="${Number(d.budget)}"></div><div class="form-field"><label>每天最多花费（EUR）</label><input id="setupDaily" type="number" min="0" step="10" value="${Number(d.daily)}"></div><div class="notice full"><i>ⓘ</i><span>系统会同时卡住“每日上限”和“每月上限”。此处是客户授权给系统的最高花费，不是必须花完的金额。</span></div><div class="form-field"><label>主要投放地区</label><input id="setupRegion" value="${esc(d.region)}" placeholder="例如：Dublin 2 · 门店周边 5 km"></div><div class="form-field full"><label>顾客范围由系统和运营设置</label><div class="recommendation-box"><span class="recommendation-icon">✦</span><div><b>客户不用猜年龄、兴趣或平台标签</b><small>系统会根据门店服务区域和推广目标给出宽泛受众建议；运营人员结合平台反馈调整。您只需确认服务区域，并告知必须排除的地区或限制。</small></div><em>默认自动优化</em></div></div></div>`:`<div class="notice" style="margin-bottom:14px"><i>✦</i><span>根据目标给出候选渠道；你可以自己勾选。只有完成客户授权并绑定广告账户的平台才可实际使用。</span></div><div class="platform-choice-grid">${platforms.map((p,i)=>`<label class="platform-choice"><input type="checkbox" name="setupPlatform" value="${p}" ${d.platforms.includes(p)?'checked':''}><span class="platform-choice-icon">${['f','♪','G','⌕','M','R'][i]}</span><span><b>${p}</b><small>${p===c.platform.replace(' Ads','')&&c.auth==='已授权'?'客户已有连接':p===c.platform.replace(' Ads','')?'需客户授权':'需独立授权后使用'}</small></span><em>${recommended.includes(p)?'推荐':''}</em></label>`).join('')}</div><div class="setup-summary"><strong>配置摘要</strong><div><span>目标</span><b>${esc(d.objective)}</b></div><div><span>月度 / 每日上限</span><b>${money(d.budget)} / ${money(d.daily)}</b></div><div><span>服务区域</span><b>${esc(d.region)}</b></div><div><span>受众建议</span><b>系统按区域和目标推荐；运营可微调</b></div><div><span>授权平台</span><b>${d.platforms.map(esc).join('、')||'请至少选择一个'}</b></div></div><div class="notice warning" style="margin-top:12px"><i>!</i><span>保存仅更新本地演示资料，不会连接账户或产生广告费用。正式系统需客户明确确认后才建立授权。</span></div>`}<div class="wizard-footer"><button class="button button-secondary" data-action="setup-prev" ${step2?'':'disabled'}>← 上一步</button><span class="result-count">步骤 ${step2?'2':'1'} / 2</span><button class="button button-primary" data-action="setup-next">${step2?'确认并保存客户配置':'下一步：查看平台建议 →'}</button></div></div></div>`;}
function readClientSetup(){let d=state.setup;if(!d)return;if(document.querySelector('#setupObjective'))d.objective=document.querySelector('#setupObjective').value;if(document.querySelector('#setupBudget'))d.budget=Math.max(0,Number(document.querySelector('#setupBudget').value)||0);if(document.querySelector('#setupDaily'))d.daily=Math.max(0,Number(document.querySelector('#setupDaily').value)||0);if(document.querySelector('#setupRegion'))d.region=document.querySelector('#setupRegion').value.trim();if(document.querySelector('#setupAudience'))d.audience=document.querySelector('#setupAudience').value;if(document.querySelector('[name="setupPlatform"]'))d.platforms=[...document.querySelectorAll('[name="setupPlatform"]:checked')].map(x=>x.value);}
function newCampaignModal(clientId=''){state.draft={clientId:clientId||state.clientId||'field',name:'工作日晚餐双人套餐优惠',objective:'预约到店',platform:'Meta',budget:20,start:'2026-11-02',days:7,copy:'想找个工作日晚餐的好去处？欢迎预约 Harbour Table 双人晚餐优惠套餐。周一至周四适用，到店出示优惠码即可享受优惠。',step:1};state.wizardStep=1;renderModal();}
function renderModal(){let d=state.draft;if(!d)return;let cl=client(d.clientId);document.querySelector('#modalRoot').innerHTML=`<div class="modal-backdrop" data-action="modal-bg"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal-head"><div><h2 id="modalTitle">${d.step===4?'投放前确认':'新建推广任务'}</h2><p>所有预算和投放状态均为本地模拟信息</p></div><button class="modal-close" data-action="close-modal" aria-label="关闭">×</button></div><div class="wizard-steps">${['基本信息','投放设置','素材预览','审批预览'].map((x,i)=>`<div class="wizard-step ${d.step===i+1?'active':d.step>i+1?'done':''}"><span>${d.step>i+1?'✓':i+1}</span>${x}</div>${i<3?'<i class="wizard-line"></i>':''}`).join('')}</div>${d.step===1?`<div class="form-grid"><div class="form-field full"><label>选择客户空间 *</label><select id="draftClient">${state.clients.map(c=>`<option value="${c.id}" ${c.id===d.clientId?'selected':''}>${esc(c.name)} · ${esc(c.auth)}</option>`).join('')}</select><span class="field-hint">账户授权、预算与报告将绑定所选客户。</span></div><div class="form-field full"><label>这次推广什么？ *</label><input id="draftName" value="${esc(d.name)}" placeholder="例如：工作日晚餐双人套餐优惠"></div><div class="form-field"><label>推荐渠道与广告账户</label><select id="draftPlatform">${['Meta','TikTok','Google','Apple Search Ads','Microsoft Ads','Reddit Ads'].map(p=>`<option ${d.platform===p?'selected':''}>${p}</option>`).join('')}</select><span class="field-hint">系统按客户已授权账户执行；本示例由客户选择 Meta。</span></div><div class="form-field"><label>投放目标</label><select id="draftObjective"><option ${d.objective==='预约到店'?'selected':''}>预约到店</option><option>在线订单</option><option>领取优惠券</option><option>电话咨询</option></select></div></div>`:d.step===2?`<div class="form-grid"><div class="form-field"><label>每日最高花费 · EUR *</label><input id="draftBudget" type="number" min="10" max="1000" value="${d.budget}"></div><div class="form-field"><label>计划天数</label><select id="draftDays">${[7,10,14,21,30].map(n=>`<option value="${n}" ${Number(d.days)===n?'selected':''}>${n} 天</option>`).join('')}</select></div><div class="form-field full"><label>开始日期</label><input id="draftStart" type="date" value="${d.start}"><span class="field-hint">本任务总上限 ${money(d.budget*d.days)} EUR；客户已授权每日最多 €20、7 天最多 €140。</span></div><div class="form-field full"><label>受众建议 · 运营可调整</label><select id="draftAudience"><option>推荐：${esc(cl.settings?.region||'客户服务区域')} · 宽泛本地受众，由平台自动优化</option><option>更近范围：门店周边约 3 km · 宽泛本地受众</option><option>扩大范围：门店周边约 8 km · 宽泛本地受众</option></select><span class="field-hint">客户不需要填写兴趣或年龄标签。系统按服务区域与目标推荐，运营根据投放反馈决定是否调整；不要为小预算过度细分。</span></div></div>`:d.step===3?`<div class="form-grid"><div class="form-field full"><label>从 PoStory 内容流程选素材</label><select id="draftCreative"><option>内容日历 · 工作日晚餐双人套餐主视觉（已获客户授权）</option><option>复用品牌菜单照片 · 自动裁切为广告尺寸</option><option>从本次优惠简报生成新图文版本 · 待客户确认</option></select><span class="field-hint">原始素材保留在 PoStory；广告版本绑定此客户与本次授权，未授权的生成素材会触发人工确认。</span></div><div class="form-field full"><label>ChatGPT 优化后的广告文案 · 运营预览</label><div class="generated-copy" id="generatedCopy">${esc(d.copy)}</div><span class="field-hint">根据已确认的优惠、使用时间和预约方式生成。客户不需要写文案；价格、限制条件或权益不明确时，先向客户核实再发布。</span><button class="button button-secondary button-small ai-refresh" data-action="ai-copy">✦ 重新优化文案</button></div><div class="form-field full"><label>素材预览</label><div class="media-placeholder">▧<strong>示例素材 · ${esc(cl.name)} 产品图</strong>模拟素材占位；此处不上传或发送任何内容。</div></div><div class="form-field"><label>优惠与核销方式</label><select><option>工作日双人晚餐 · 到店出示优惠码</option><option>预约后到店核销</option></select></div><div class="form-field"><label>顾客下一步</label><input value="在线预约 · 到店出示优惠码核销" readonly></div></div>`:`<div class="review-banner">系统检查客户已授权范围。范围内常规任务自动执行；新优惠、预算越界或账户异常才会进入人工审批。</div><div class="split-cards"><div class="info-box"><small>客户 / 广告账户</small><b>${esc(cl.name)} · ${esc(cl.account)}</b></div><div class="info-box"><small>平台 / 目标</small><b>${esc(d.platform)} · ${esc(d.objective)}</b></div><div class="info-box"><small>每日上限 / 周期</small><b>${money(d.budget)} × ${d.days} 天</b></div><div class="info-box"><small>任务总上限 · EUR</small><b>${money(d.budget*d.days)}</b></div></div><div class="notice warning" style="margin-top:13px"><i>!</i><span>${cl.auth==='已授权'?'符合客户授权时按规则启动；演示按钮仅模拟状态，不会真实投放。':'该客户尚未授权；计划可保存为草稿，但无法进入审批或启动。'}</span></div>`}<div class="wizard-footer"><button class="button button-secondary" data-action="wizard-prev" ${d.step===1?'disabled':''}>← 上一步</button><span class="result-count">步骤 ${d.step} / 4</span><button class="button button-primary" data-action="wizard-next">${d.step===4?'确认并运行模拟':'下一步 →'}</button></div></div></div>`;}
function readDraft(){let d=state.draft;if(!d)return;if(document.querySelector('#draftClient'))d.clientId=document.querySelector('#draftClient').value;if(document.querySelector('#draftName'))d.name=document.querySelector('#draftName').value.trim();if(document.querySelector('#draftPlatform'))d.platform=document.querySelector('#draftPlatform').value;if(document.querySelector('#draftObjective'))d.objective=document.querySelector('#draftObjective').value;if(document.querySelector('#draftBudget'))d.budget=Math.max(10,Number(document.querySelector('#draftBudget').value)||10);if(document.querySelector('#draftDays'))d.days=Number(document.querySelector('#draftDays').value);if(document.querySelector('#draftStart'))d.start=document.querySelector('#draftStart').value;if(document.querySelector('#draftCopy'))d.copy=document.querySelector('#draftCopy').value;if(document.querySelector('#draftAudience'))d.audience=document.querySelector('#draftAudience').value;if(document.querySelector('#draftCreative'))d.creative=document.querySelector('#draftCreative').value;}
function finishDraft(){let d=state.draft,cl=client(d.clientId);let id='CMP-'+(1050+state.campaigns.length);let allowedPlatforms=cl.settings?.platforms||[cl.platform.replace(' Ads','')];let withinPolicy=cl.auth==='已授权'&&!d.exception&&d.budget<=(cl.settings?.daily??20)&&d.budget*d.days<=(cl.settings?.policy?.total??140)&&allowedPlatforms.includes(d.platform)&&d.objective===(cl.settings?.objective||d.objective);let status=withinPolicy?'投放中':cl.auth==='已授权'?'待审批':'草稿';state.campaigns.unshift({id,name:d.name||'新推广任务',clientId:d.clientId,platform:d.platform,objective:d.objective,budget:d.budget,spent:0,status,approval:withinPolicy?'已通过':cl.auth==='已授权'?'待审批':'待授权',progress:withinPolicy?18:0,date:`${d.start.slice(5).replace('-','/')} – ${d.start.slice(5).replace('-','/')}`,roas:'—'});if(cl.auth==='已授权'&&!withinPolicy)state.approvals.unshift({id:'APR-'+String(92+state.approvals.length).padStart(3,'0'),campaignId:id,clientId:d.clientId,name:d.name||'新推广任务',submitted:'刚刚',note:d.exception?'超过客户授权的预算边界，需要客户/运营确认。':'需要核实授权或策略范围。',status:'待审批'});state.draft=null;document.querySelector('#modalRoot').innerHTML='';state.page=withinPolicy?'delivery':cl.auth==='已授权'?'approvals':'campaigns';render();toast(withinPolicy?'任务在授权范围内，已通过自动预检并进入模拟投放状态':'超出授权范围，已转人工审批','ok');}
function showAuth(c){document.querySelector('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><div><h2>邀请客户完成平台授权</h2><p>${esc(c.name)} · ${esc(c.platform)}</p></div><button class="modal-close" data-action="close-modal">×</button></div><div class="notice" style="margin-bottom:14px"><i>ⓘ</i><span>正式流程会为该客户生成一次性授权链接。客户登录广告平台并确认授权后，系统仅关联其所选广告账户。</span></div><div class="split-cards"><div class="info-box"><small>收件人</small><b>${esc(c.contact)}</b></div><div class="info-box"><small>邮箱</small><b>${esc(c.email)}</b></div><div class="info-box"><small>客户空间</small><b>${esc(c.name)}</b></div><div class="info-box"><small>申请权限</small><b>读取报告 + 管理广告</b></div></div><div class="notice warning" style="margin-top:14px"><i>!</i><span>演示会直接更改模拟状态。不会发送邮件、访问平台或获得授权令牌。</span></div><div class="modal-actions"><button class="button button-secondary" data-action="close-modal">稍后</button><button class="button button-primary" data-action="finish-auth" data-id="${c.id}">模拟完成授权</button></div></div></div>`;}
function detailCampaign(id){let c=campaign(id);if(!c)return;let cl=client(c.clientId);document.querySelector('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><div><h2>${esc(c.name)}</h2><p>${esc(c.id)} · ${esc(cl.name)} · v1 计划预览</p></div><button class="modal-close" data-action="close-modal">×</button></div><div class="split-cards"><div class="info-box"><small>投放账户</small><b>${esc(cl.account)}</b></div><div class="info-box"><small>计划状态</small><b>${esc(c.status)}</b></div><div class="info-box"><small>每日预算</small><b>${money(c.budget)} EUR</b></div><div class="info-box"><small>总预算上限</small><b>${money(c.budget*10)} EUR</b></div><div class="info-box"><small>平台 / 目标</small><b>${esc(c.platform)} · ${esc(c.objective)}</b></div><div class="info-box"><small>审批状态</small><b>${esc(c.approval)}</b></div></div><div class="notice warning" style="margin-top:14px"><i>!</i><span>预算、计划和投放数据均为演示值。真实系统上线前需实现预算硬限制和审批版本校验。</span></div><div class="modal-actions"><button class="button button-secondary" data-action="close-modal">关闭</button></div></div></div>`;}
function downloadCsv(){let rows=[['客户','推广任务','平台','状态','每日预算 EUR','模拟消耗 EUR','ROAS'],...state.campaigns.map(c=>[client(c.clientId).name,c.name,c.platform,c.status,c.budget,c.spent,c.roas])];let csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='postory-ads-demo-report.csv';a.click();URL.revokeObjectURL(a.href);toast('演示 CSV 已下载（不含平台真实数据）','ok');}
document.body.addEventListener('click',e=>{let btn=e.target.closest('[data-page],[data-action]');if(!btn)return;if(btn.dataset.page){if(btn.dataset.page==='client-detail')state.page='client-detail';else state.page=btn.dataset.page;state.portal=false;render();return;}let a=btn.dataset.action,id=btn.dataset.id;
if(a==='client'){state.clientId=id;state.clientTab='overview';state.page='client-detail';state.portal=false;render();}
else if(a==='new-campaign')newCampaignModal(btn.dataset.client||'');
else if(a==='new-client')newClientModal();
else if(a==='create-demo-client'){let name=document.querySelector('#newClientName')?.value.trim();if(!name){toast('请填写客户名称','warn');return;}let contact=document.querySelector('#newClientContact')?.value.trim()||'客户联系人';let email=document.querySelector('#newClientEmail')?.value.trim()||'未填写';let sector=document.querySelector('#newClientSector')?.value||'其他';let initials=name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();let c={id:'client-'+Date.now(),name,initials,tone:'blue',sector,contact,email,platform:'Meta Ads',account:'待客户授权',auth:'待授权',spend:0,roas:'—',campaigns:0,description:`${sector}客户空间 · 等待首次配置`};state.clients.unshift(c);state.clientId=c.id;state.page='client-detail';document.querySelector('#modalRoot').innerHTML='';render();clientSetupModal(c.id);}
else if(a==='client-setup')clientSetupModal(btn.dataset.client||state.clientId);
else if(a==='close-modal'){state.draft=null;state.setup=null;document.querySelector('#modalRoot').innerHTML='';}
else if(a==='setup-prev'){readClientSetup();state.setup.step=1;renderClientSetup();}
else if(a==='setup-next'){readClientSetup();let d=state.setup;if(d.step===1){if(!d.objective||!d.region||d.daily<0||d.budget<d.daily){toast('请检查预算：月度上限应不低于每日上限','warn');return;}const connected=client(d.clientId).platform.replace(' Ads','');d.platforms=d.objective.includes('视频')?['TikTok',connected]:d.objective.includes('网站访问')?['Google',connected]:[connected];d.platforms=[...new Set(d.platforms)];d.step=2;renderClientSetup();}else{if(!d.platforms.length){toast('请至少选择一个渠道','warn');return;}let c=client(d.clientId);c.settings={...(c.settings||{}),objective:d.objective,budget:d.budget,daily:d.daily,region:d.region,audience:d.audience,platforms:d.platforms,currency:'EUR',confirmedAt:new Date().toISOString()};c.platform=d.platforms[0]+' Ads';document.querySelector('#modalRoot').innerHTML='';state.setup=null;state.page='client-detail';state.clientId=c.id;render();toast('客户首次配置已保存到本地演示数据','ok');}}
else if(a==='wizard-next'){readDraft();let d=state.draft;if(d.step===1&&!d.name){toast('请先填写计划名称','warn');document.querySelector('#draftName')?.focus();return;}if(d.step===1&&client(d.clientId).auth!=='已授权'){toast('当前客户尚未授权，计划可以保存为草稿','warn');}if(d.step===2){let cl=client(d.clientId);let maxDaily=cl.settings?.daily??20;let maxTotal=cl.settings?.policy?.total??140;d.exception=d.budget>maxDaily||d.budget*d.days>maxTotal;if(d.exception){toast(`超出客户授权上限（${money(maxDaily)}/天，${money(maxTotal)}/任务），将转人工审批`,'warn');}}if(d.step<4){d.step++;renderModal();}else finishDraft();}
else if(a==='wizard-prev'){readDraft();state.draft.step=Math.max(1,state.draft.step-1);renderModal();}
else if(a==='client-tab'){state.clientTab=btn.dataset.tab;render();}
else if(a==='portal-tab'){state.portalTab=btn.dataset.tab;render();}
else if(a==='client-preview'||a==='client-portal'){state.portal=true;state.portalTab='overview';render();}
else if(a==='client-report'){state.clientId=btn.dataset.client;state.portal=true;state.portalTab='reports';render();}
else if(a==='exit-portal'){state.portal=false;render();}
else if(a==='authorize'){showAuth(client(id));}
else if(a==='finish-auth'){let c=client(id);c.auth='已授权';c.spend=0;c.roas='—';c.campaigns=0;c.account=`${c.name} · ${Math.floor(1000+Math.random()*8000)}`;document.querySelector('#modalRoot').innerHTML='';render();toast(`${c.name} 已完成模拟授权`,'ok');}
else if(a==='revoke-auth'){let c=client(id);c.auth='待授权';render();toast(`${c.name} 的模拟授权已撤销`,'warn');}
else if(a==='approve'){let ap=state.approvals.find(x=>x.id===id);if(!ap)return;let cl=client(ap.clientId);if(cl.auth!=='已授权'){toast('授权未完成，已阻止审批','warn');return;}let ca=campaign(ap.campaignId);ap.status='已通过';ap.approvedBy='Emily Lin';ca.status='已批准';ca.approval='已通过';render();toast('审批已通过；计划仍需手动模拟启动','ok');}
else if(a==='reject'){let ap=state.approvals.find(x=>x.id===id);if(!ap)return;ap.status='已退回';ap.note='已退回修改，请补充受众和预算说明。';let ca=campaign(ap.campaignId);if(ca){ca.status='草稿';ca.approval='已退回';}render();toast('计划已退回运营修改','warn');}
else if(a==='simulate'){let ca=campaign(id);if(!ca)return;let cl=client(ca.clientId);if(ca.approval!=='已通过'&&ca.status!=='投放中'&&ca.status!=='学习中'){toast('请先完成审批','warn');return;}if(cl.auth!=='已授权'){toast('客户授权已失效，无法启动','warn');return;}if(ca.status==='已批准'){ca.status='学习中';ca.spent=Number((ca.spent+ca.budget*.28).toFixed(2));ca.progress=18;toast('模拟账户进入学习期','ok');}else if(ca.progress>=95){ca.status='已完成';ca.progress=100;toast('模拟计划已完成','ok');}else{ca.status='投放中';ca.spent=Number((ca.spent+ca.budget*.68).toFixed(2));ca.progress=Math.min(100,ca.progress+24);ca.roas=(2.7+Math.random()*1.3).toFixed(2)+'×';toast('已模拟推进 1 天 · 消耗和转化均为虚构','ok');}render();}
else if(a==='pause'){let ca=campaign(id);ca.status='暂停';render();toast('计划已暂停（模拟）','warn');}
else if(a==='resume'){let ca=campaign(id);ca.status='投放中';render();toast('计划已恢复（模拟）','ok');}
else if(a==='campaign-detail')detailCampaign(id);
else if(a==='ai-copy'){if(!state.draft)return;state.draft.copy=state.draft.copy.includes('想找个工作日晚餐')?'周一至周四，来 Harbour Table 享受轻松的双人晚餐时光。提前预约，到店出示优惠码，即可享双人套餐优惠。':'想找个工作日晚餐的好去处？欢迎预约 Harbour Table 双人晚餐优惠套餐。周一至周四适用，到店出示优惠码即可享受优惠。';renderModal();toast('已生成新的文案版本，请运营核对优惠事实','ok');}else if(a==='report-download')downloadCsv();
else if(a==='toast')toast(btn.dataset.message||'已完成');
else if(a==='modal-bg'&&e.target===btn){document.querySelector('#modalRoot').innerHTML='';state.draft=null;}
});
document.querySelector('#clientPreview').addEventListener('click',()=>{state.clientId=state.clientId||'maple';state.portal=true;state.portalTab='overview';render();});
document.querySelector('#resetDemo').addEventListener('click',()=>{localStorage.removeItem('postoryAdsDemo');state=structuredClone(SEED);document.querySelector('#modalRoot').innerHTML='';render();toast('演示数据已恢复初始状态','ok');});
document.body.addEventListener('input',e=>{if(e.target.id==='clientSearch'||e.target.id==='clientFilter')filterClients();if(e.target.id==='campaignSearch'||e.target.id==='campaignFilter'||e.target.id==='campaignClient')filterCampaigns();});
function filterClients(){let q=(document.querySelector('#clientSearch')?.value||'').toLowerCase(),status=document.querySelector('#clientFilter')?.value||'all';document.querySelectorAll('[data-client-card]').forEach(el=>{let c=client(el.dataset.clientCard);el.hidden=!(c.name.toLowerCase().includes(q)||c.contact.toLowerCase().includes(q))&&false;el.hidden=(!c.name.toLowerCase().includes(q)&&!c.contact.toLowerCase().includes(q))||(status!=='all'&&c.auth!==status);});}
function filterCampaigns(){if(!document.querySelector('#campaignTable'))return;let q=(document.querySelector('#campaignSearch')?.value||'').toLowerCase(),s=document.querySelector('#campaignFilter')?.value||'all',cid=document.querySelector('#campaignClient')?.value||'all';let list=state.campaigns.filter(c=>(q===''||c.name.toLowerCase().includes(q)||client(c.clientId).name.toLowerCase().includes(q))&&(s==='all'||c.status===s)&&(cid==='all'||c.clientId===cid));document.querySelector('#campaignTable').innerHTML=campaignTable(list);}
render();
